(()=>{'use strict';const S=MartinsSupabaseConexao,$=id=>document.getElementById(id);let client=null,usedConfig=null,busy=false,auth=false,authorized=false;const say=s=>$('sb-status').textContent=s;
function controls(){for(const id of ['sb-config','sb-url','sb-key','sb-email','sb-password','sb-negative-id'])$(id).disabled=busy;$('sb-login').disabled=busy||!client;$('sb-logout').disabled=busy||!auth;$('sb-company').disabled=busy||!auth;$('sb-authorize').disabled=busy||!auth;$('sb-diagnose').disabled=busy||!authorized;$('sb-negative').disabled=busy||!authorized;}
function resetView(){$('sb-results').replaceChildren();$('sb-company').replaceChildren();$('sb-user').textContent='';auth=false;authorized=false;}
async function run(fn){if(busy)return;busy=true;controls();try{await fn();}catch(e){say(e.message);if(!client?.state().empresaId)authorized=false;if(!client?.state().autenticado){auth=false;authorized=false;$('sb-results').replaceChildren();}}finally{busy=false;controls();}}
$('sb-config').onclick=()=>run(async()=>{const candidate=S.config({url:$('sb-url').value,key:$('sb-key').value});client?.disconnect();client=S.create(candidate);usedConfig=candidate;resetView();$('sb-project').textContent='Projeto selecionado: '+new URL(candidate.url).hostname;say('Configuração pública validada localmente. Nenhuma conexão foi feita.');});
for(const id of ['sb-url','sb-key'])$(id).oninput=()=>{client?.disconnect();client=null;usedConfig=null;resetView();$('sb-project').textContent='Configuração alterada: confirme antes de conectar.';controls();};
$('sb-login').onclick=()=>run(async()=>{if(!client||!usedConfig)throw Error('Confirme a configuração');resetView();const password=$('sb-password').value;try{const result=await client.signIn($('sb-email').value,password);auth=true;$('sb-user').textContent='Identidade confirmada no servidor: '+result.user.email;for(const p of result.profiles){const option=new Option(p.empresa_id+' · '+p.papel+(p.ativo?'':' (inativo)'),p.empresa_id);option.disabled=!p.ativo||p.papel!=='administrador';$('sb-company').add(option);}const first=result.profiles.find(p=>p.ativo&&p.papel==='administrador');if(first)$('sb-company').value=first.empresa_id;say(first?'Login real confirmado. Verifique a empresa antes de consultar.':'Login confirmado, mas nenhum perfil ativo de administrador foi liberado.');}finally{$('sb-password').value='';}});
$('sb-authorize').onclick=()=>run(async()=>{authorized=false;$('sb-results').replaceChildren();const result=await client.authorize($('sb-company').value);authorized=true;say('Função existente autorizou o administrador da empresa '+result.empresaId+'. Não foi executado SQL de alteração.');});$('sb-company').onchange=()=>{authorized=false;$('sb-results').replaceChildren();controls();say('Empresa alterada. Verifique a autorização novamente.');};
$('sb-diagnose').onclick=()=>run(async()=>{$('sb-results').replaceChildren();const report=await client.diagnose();for(const r of report.results){const tr=document.createElement('tr');for(const value of [r.tabela,r.status]){const td=document.createElement('td');td.textContent=value;tr.append(td);}$('sb-results').append(tr);}say(report.observacao+'\nTabelas com consulta aceita: '+report.results.filter(r=>r.ok).length+'/'+report.results.length+'. RLS completa: pendente.');});
$('sb-negative').onclick=()=>run(async()=>{try{const result=await client.negative($('sb-negative-id').value.trim());say(result.observacao);}catch(e){authorized=false;throw e;}});$('sb-logout').onclick=()=>run(async()=>{const result=await client.signOut();resetView();say(result.servidor?'Sessão encerrada no servidor e nesta página.':'Sessão removida desta página; encerramento remoto não confirmado.');});
const provided=window.MARTINS_SUPABASE_PUBLIC_CONFIG;if(provided?.url||provided?.key){try{const c=S.config(provided);$('sb-url').value=c.url;$('sb-key').value=c.key;$('sb-project').textContent='Configuração pública preenchida pelo pacote; confirme para usar.';}catch{say('Configuração pública do pacote inválida. Informe os dados corretos.');}}controls();
})();
